{
  "name": "shiritori-fighter",
  "version": "1.1.0",
  "private": true,
  "description": "ことばで戦え！声でも遊べるしりとりバトルゲーム",
  "license": "MIT",
  "type": "module",
  "scripts": {
    "check": "node scripts/check-standard.mjs && node tools/build-sw.mjs --check && node scripts/check-project.mjs",
    "test": "node --test \"tests/*.test.mjs\"",
    "build:sw": "node tools/build-sw.mjs"
  }
}

{
  "name": "shared-folder-sync",
  "version": "1.0.0",
  "private": true,
  "description": "共有フォルダ同期くん — GAS。実行コードは 1 バイトも外から取らない",
  "type": "module",
  "scripts": {
    "build": "node tools/vendor/build-vendor.mjs",
    "build:fonts": "node tools/fonts/build-fonts.mjs",
    "verify": "node tools/build-app-links.mjs --check && node tools/vendor/verify-generated.mjs",
    "ci": "npm run build && npm run verify",
    "build:app-links": "node tools/build-app-links.mjs"
  },
  "dependencies": {
    "bootstrap": "5.3.0",
    "bootstrap-icons": "1.10.5",
    "sweetalert2": "11.26.25"
  }
}

{
  "name": "keisan-block",
  "version": "1.0.0",
  "description": "さんすうブロック — 小学1年生向けの けいさん れんしゅう（PWA）",
  "private": true,
  "license": "MIT",
  "type": "module",
  "_comment": "依存パッケージは持たない。ブラウザへ送る実行コードは 0 バイトで、ビルドもしない。ここにあるのは検査を走らせるための入口だけ。",
  "scripts": {
    "check": "node scripts/check-standard.mjs && node tools/build-sw.mjs --check && node scripts/check-project.mjs",
    "check:json": "node scripts/check-project.mjs --json",
    "test": "node --test tests/*.test.mjs",
    "icons": "python3 tools/make-icons.py",
    "serve": "python3 -m http.server 8000",
    "build:sw": "node tools/build-sw.mjs"
  },
  "engines": {
    "node": ">=20"
  }
}

{
  "name": "ice_slide-puzzle",
  "private": true,
  "version": "1.0.0",
  "description": "南極スライダー。ビルドは不要で、index.html をそのまま配信している。ここにあるのはアイコンを作り直すための道具だけ。",
  "type": "module",
  "scripts": {
    "icons": "node tools/optimize-icons.mjs",
    "build:sw": "node tools/build-sw.mjs",
    "check": "node scripts/check-standard.mjs && node tools/build-sw.mjs --check"
  },
  "devDependencies": {
    "sharp": "^0.35.3"
  }
}

{
  "name": "gobblet",
  "version": "2.2.0",
  "description": "パクパクゴブレット - 3D風のコマをかぶせて遊ぶ対戦型ボードゲーム",
  "main": "server.js",
  "type": "module",
  "license": "MIT",
  "scripts": {
    "dev": "node server.js",
    "build": "echo 'No build required'",
    "lint": "echo 'No lint required'",
    "start": "node server.js",
    "test": "node --test \"tests/**/*.test.mjs\"",
    "check": "node tools/build-sw.mjs --check && node scripts/check-project.mjs",
    "build:sw": "node tools/build-sw.mjs"
  },
  "dependencies": {
    "express": "^4.19.2"
  }
}

{
  "name": "digital-newspaper",
  "version": "2.0.0",
  "private": true,
  "license": "MIT",
  "scripts": {
    "check": "node scripts/check-project.mjs",
    "test": "node --test tests/*.test.mjs",
    "ci": "npm test && npm run check && npm run build:sw -- --check",
    "build:sw": "node tools/build-sw.mjs"
  }
}

